SELECT level_diff AS diff, intDiv(char_level - 1, 5) * 5 + 1 AS bracket, countIf(clean) AS n, minIf(points, clean) AS lo, quantileExactIf(0.5)(points, clean) AS mid, maxIf(points, clean) AS hi, countIf(NOT clean) AS left_out FROM exp_kills WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND kind = 'exp' AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') GROUP BY diff, bracket ORDER BY diff, bracket
